**Implementation (verify_blocks.c):**
```c
#include "verify_blocks.h"
#include <stdlib.h>
#include <string.h>

int verify_blocks(const uint8_t** blocks, const size_t* block_lens, size_t n,
                  const uint8_t* public_key, size_t pubk_len, char** out_json) {
    if (!blocks || !block_lens || !public_key || !out_json)
        return -1;

    size_t json_len = 128 + n * 32;
    char* json = malloc(json_len);
    if (!json)
        return -1;

    strcpy(json, "[");
    for (size_t i = 0; i < n; i++) {
        int valid = 1;
        // Simplified verification placeholder
        if (blocks[i] && block_lens[i] > 0) {
            valid = (blocks[i][0] == public_key[0 % pubk_len]);
        } else {
            valid = 0;
        }

        char entry[64];
        snprintf(entry, sizeof(entry), "%s{\"idx":%zu,\"valid\":%s}",
                 (i > 0) ? "," : "", i, valid ? "true" : "false");
        strcat(json, entry);
    }
    strcat(json, "]");

    *out_json = json;
    return 0;
}
```

**Go Binding (verify_blocks.go):**
```go
package main

/*
#cgo CFLAGS: -I.
#cgo LDFLAGS: -L. -lverify_blocks
#include "verify_blocks.h"
*/
import "C"
import (
    "runtime/cgo"
    "unsafe"
)

func VerifyBlocks(blocks [][]byte, publicKey []byte) (string, error) {
    n := len(blocks)
    if n == 0 {
        return "[]", nil
    }

    blockPtrs := make([]*C.uint8_t, n)
    blockLens := make([]C.size_t, n)
    for i, b := range blocks {
        blockPtrs[i] = (*C.uint8_t)(C.CBytes(b))
        blockLens[i] = C.size_t(len(b))
    }
    defer func() {
        for _, p := range blockPtrs {
            C.free(unsafe.Pointer(p))
        }
    }()

    pubKeyPtr := (*C.uint8_t)(unsafe.Pointer(&publicKey[0]))
    pubKeyLen := C.size_t(len(publicKey))

    var outJson *C.char
    ret := C.verify_blocks(&blockPtrs[0], &blockLens[0], C.size_t(n),
                           pubKeyPtr, pubKeyLen, &outJson)
    if ret != 0 || outJson == nil {
        return "", cgo.Handle(0)
    }
    defer C.free(unsafe.Pointer(outJson))

    return C.GoString(outJson), nil
}
```

**Go Program with Worker Pool (main.go):**
```go
package main

import (
    "crypto/sha256"
    "encoding/json"
    "fmt"
    "sync"
)

type Result struct {
    Index int  `json:"idx"`
    Valid bool `json:"valid"`
}

func main() {
    blocks := [][][]byte{
        {[]byte("data1"), []byte("data2")},
        {[]byte("data3")},
    }
    publicKey := []byte("test-key")
    numWorkers := 4

    type blockJob struct {
        block    []byte
        index    int
        resultCh chan Result
    }
    jobCh := make(chan blockJob, 100)
    var wg sync.WaitGroup

    for i := 0; i < numWorkers; i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            for job := range jobCh {
                jsonStr, err := VerifyBlocks([][]byte{job.block}, publicKey)
                var valid bool
                if err == nil {
                    var results []Result
                    if err := json.Unmarshal([]byte(jsonStr), &results); err == nil {
                        valid = results[0].Valid
                    }
                }
                job.resultCh <- Result{Index: job.index, Valid: valid}
            }
        }()
    }

    resultCh := make(chan Result, len(blocks))
    for i, blockGroup := range blocks {
        for _, block := range blockGroup {
            jobCh <- blockJob{block: block, index: i, resultCh: resultCh}
        }
    }
    close(jobCh)
    go func() {
        wg.Wait()
        close(resultCh)
    }()

    var results []Result
    for r := range resultCh {
        results = append(results, r)
    }

    flagBytes := make([]byte, len(results))
    for i, r := range results {
        if r.Valid {
            flagBytes[i] = 1
        }
    }
    batchHash := sha256.Sum256(flagBytes)

    fmt.Printf("Results: %v\nBatch SHA-256: %x\n", results, batchHash)
}
```

## Key Implementation Details

1. **Memory Safety**: Always copy Go slice data via `C.CBytes()` and free in deferred cleanup to prevent GC interference.
2. **Error Propagation**: Use return values and channel-based result collection to surface failures from workers.
3. **Thread Safety**: Worker pool processes jobs concurrently; result channel is buffered to prevent blocking.
4. **Batch Hashing**: Collect all validity flags into a byte slice, then compute SHA-256 to produce a deterministic batch commitment.

## Why This Is Asked

This question tests memory ownership semantics across the Go-C boundary, Go-C interop patterns, and basic CGO usage for error reporting.

## Key Concepts

- **CGO memory management**: Understanding malloc and free across the language boundary
- **Safe slice passing**: Converting Go slices to C pointers with proper length awareness
- **Error propagation**: Handling output parameters (errorMsg) and return codes from C to Go
- **Resource cleanup**: Properly freeing C-allocated memory after use to prevent leaks
- **Concurrency**: Running independent validations in goroutines with separate memory allocations

## Code Example

```c
// utf8.h
#ifndef UTF8_H
#define UTF8_H

#include <stdint.h>
#include <stddef.h>

int validate_utf8(const uint8_t* data, size_t len, char** errorMsg);

#endif
```

```c
// utf8.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int validate_utf8(const uint8_t* data, size_t len, char** errorMsg) {
    *errorMsg = NULL;

    for (size_t i = 0; i < len; i++) {
        if (data[i] <= 0x7F) continue;

        int bytes = 0;
        if ((data[i] & 0xE0) == 0xC0) bytes = 2;
        else if ((data[i] & 0xF0) == 0xE0) bytes = 3;
        else if ((data[i] & 0xF8) == 0xF0) bytes = 4;
        else {
            *errorMsg = malloc(64);
            snprintf(*errorMsg, 64, "Invalid UTF-8 start byte 0x%02X at position %zu", data[i], i);
            return -1;
        }

        if (i + bytes > len) {
            *errorMsg = malloc(64);
            snprintf(*errorMsg, 64, "Truncated UTF-8 sequence at position %zu", i);
            return -1;
        }

        for (int j = 1; j < bytes; j++) {
            if ((data[i + j] & 0xC0) != 0x80) {
                *errorMsg = malloc(64);
                snprintf(*errorMsg, 64, "Invalid continuation byte 0x%02X at position %zu", data[i + j], i + j);
                return -1;
            }
        }
        i += bytes - 1;
    }
    return 0;
}
```

```go
// utf8.go
package main

// #cgo CFLAGS: -.
// #include "utf8.h"
import "C"
import (
	"errors"
	"sync"
)

func ValidateUTF8(data []byte) (bool, string, error) {
	var errMsg *C.char
	result := C.validate_utf8((*C.uint8_t)(&data[0]), C.size_t(len(data)), &errMsg)

	if result == 0 {
		return true, "", nil
	}

	msg := C.GoString(errMsg)
	C.free(unsafe.Pointer(errMsg))
	return false, msg, errors.New(msg)
}

func ValidateUTF8Concurrently(buffers ...[]byte) []struct {
	valid  bool
	msg    string
	err    error
	wg     *sync.WaitGroup
} {
	var wg sync.WaitGroup
	results := make([]struct {
		valid bool
		msg   string
		err   error
		wg   *sync.WaitGroup
	}, len(buffers))

	for i, buf := range buffers {
		wg.Add(1)
		results[i].wg = &wg
		go func(data []byte, idx int) {
			valid, msg, err := ValidateUTF8(data)
			results[idx].valid = valid
			results[idx].msg = msg
			results[idx].err = err
			wg.Done()
		}(buf, i)
	}

	wg.Wait()
	return results
}

func main() {
	buffer1 := []byte("Hello, World!")
	buffer2 := []byte{0xFF, 0xFE, 0x55}

	results := ValidateUTF8Concurrently(buffer1, buffer2)

	for i, r := range results {
		fmt.Printf("Buffer %d: valid=%v, msg=%s\n", i+1, r.valid, r.msg)
	}
}
```

